[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RequestPath,[string[]]$RoundPaths=@('ES/Output/WebPageStudio/bootstrap/round-01-intake-github.json','ES/Output/WebPageStudio/bootstrap/round-02-focus-github.json','ES/Output/WebPageStudio/bootstrap/round-03-task-context-github.json','ES/Output/WebPageStudio/bootstrap/round-04-knowledge-route-github.json','ES/Output/WebPageStudio/bootstrap/round-05-design-packet-github.json'))
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';function F([string]$p){if([IO.Path]::IsPathRooted($p)){[IO.Path]::GetFullPath($p)}else{[IO.Path]::GetFullPath((Join-Path (Get-Location) $p))}}
$reqPath=F $RequestPath;if(-not(Test-Path $reqPath -PathType Leaf)){throw 'BLOCKED_ESWEB_REQUEST_MISSING'};$req=Get-Content $reqPath -Raw -Encoding UTF8|ConvertFrom-Json;$objective=[string]$req.objective
$rows=@();$missing=@();$combined='';for($i=0;$i -lt 5;$i++){if($i -ge $RoundPaths.Count){$missing+="round-$($i+1)";continue};$p=F $RoundPaths[$i];if(-not(Test-Path $p -PathType Leaf)){$missing+=$RoundPaths[$i];continue};$raw=Get-Content $p -Raw -Encoding UTF8;$combined+=$raw;$rows+=[ordered]@{round=$i+1;path=$RoundPaths[$i].Replace('\','/');sha256=(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant();bytes=([Text.Encoding]::UTF8.GetByteCount($raw))}}
$matched=(-not [string]::IsNullOrWhiteSpace($objective)) -and ($combined -match [regex]::Escape($objective));$status=if($missing.Count -gt 0 -or -not $matched){'blocked'}else{'accepted'};$reason=if($missing.Count -gt 0){'BLOCKED_ESWEB_ROUNDS_MISSING_REPLAN_REQUIRED'}elseif(-not $matched){'BLOCKED_ESWEB_ROUNDS_MISMATCH_REPLAN_REQUIRED'}else{'ROUND_CONTEXT_MATCHED'}
[ordered]@{schemaVersion=1;recordType='ESWebRoundContinuityGateReceipt';status=$status;reasonCode=$reason;requestPath=$RequestPath.Replace('\','/');objective=$objective;matched=$matched;roundCount=$rows.Count;rounds=$rows;replanRequired=($status -eq 'blocked');nonClaims=@('does not prove browser or runtime behavior','accepted means only that current Round01-05 text matches the request objective') }|ConvertTo-Json -Depth 12;if($status -eq 'blocked'){exit 1}
